/// Acquires exclusive external control of the sibling Animator.
///
/// The first owner wins until it releases the override. Re-acquiring from
/// the same owner is idempotent, while another owner is rejected so two
/// sequencers cannot silently fight over one Animator.
pub fn acquire_external_override(&mut self, owner: engine_ecs::Entity) -> bool {
    match self.external_override_owner {
        None => {
            self.external_override_owner = Some(owner);
            true
        }
        Some(current) => current == owner,
    }
}

/// Releases external Animator control when `owner` still owns it.
///
/// Re-entering the current graph state on the next graph tick restores the
/// controller without changing its state-machine state or parameters.
pub fn release_external_override(&mut self, owner: engine_ecs::Entity) {
    if self.external_override_owner == Some(owner) {
        self.external_override_owner = None;
        self.entered = false;
    }
}

/// Returns the current external Animator owner, when graph evaluation is suspended.
pub fn external_override_owner(&self) -> Option<engine_ecs::Entity> {
    self.external_override_owner
